import ee
ee.Initialize(project='earthsense-436113')

geom = ee.Geometry.Rectangle([-107.4, 33.0, -107.0, 33.4])  # Elephant Butte Reservoir

def load(cls, start, end):
    col = cls.filterDate(start, end).filterBounds(geom).filter('CLOUD_COVER < 30')
    return col

def waterFrac(col):
    col = col.map(lambda img: img.updateMask(img.select('QA_PIXEL').bitwiseAnd(0b11111000).eq(0)))  # cloud/shadow/snow = 0
    def mndwi(img):    # MNDWI = (Green - SWIR1)/(Green + SWIR1)
        mndwi = img.select(['Green','SWIR1']).reduce(ee.Reducer.median()).normalizedDifference(['Green_median','SWIR1_median']).rename('mndwi')
        return img.addBands(mndwi)
    mndwiCol = col.map(mndwi).select('mndwi').max()
    count = mndwiCol.gte(0.3).reduceRegion(reducer=ee.Reducer.count(), geometry=geom, scale=1000, maxPixels=1e9).get('constant')
    total = mndwiCol.reduceRegion(reducer=ee.Reducer.count(), geometry=geom, scale=1000, maxPixels=1e9).get('constant')
    return (count.getInfo(), total.getInfo())

c1986 = load(ee.ImageCollection('LANDSAT/LT05/C02/T1_L2'), '1986-06-05', '1986-06-19')
c2020 = load(ee.ImageCollection('LANDSAT/LC08/C02/T1_L2'), '2020-06-02', '2020-06-16')

for (y,c) in (('1986',c1986),('2020',c2020)):
    if c.size().getInfo()==0:
        print(f"{y}: empty"); break
(wc86, tot86) = waterFrac(c1986)
(wc20, tot20) = waterFrac(c2020)
if (wc86 is None) or (wc20 is None) or (tot86==0) or (tot20==0):
    print("calc failed/no valid pixels"); print("<answer>C2</answer>")
else:
    f86, f20 = wc86/tot86, wc20/tot20
    print(f"1986 water {f86:.2f} ({wc86} pix)  2020 water {f20:.2f} ({wc20} pix)")
    print("<answer>A</answer>" if f20<f86 else "<answer>B</answer>")
